<?php
namespace App\Services; use App\Enums\{OrderStatus, PaymentStatus, UserRole}; use App\Models\{Order, Payment, Referral, User, Withdrawal};
class DashboardService { public function for(User $user): array { return match($user->role) { UserRole::Worker => $this->worker($user), UserRole::Customer => $this->customer($user), UserRole::Affiliate => $this->affiliate($user), default => $this->owner() }; } public function owner(): array { return ['totalRevenue'=>Payment::where('status',PaymentStatus::Paid)->sum('amount'), 'monthlyProfit'=>Payment::where('status',PaymentStatus::Paid)->whereMonth('paid_at',now()->month)->sum('amount') - Order::whereMonth('completed_at',now()->month)->sum('worker_fee'), 'activeOrders'=>Order::whereNotIn('status',[OrderStatus::Completed,OrderStatus::Cancelled])->count(), 'delayedOrders'=>Order::whereNotIn('status',[OrderStatus::Completed,OrderStatus::Cancelled])->where('deadline','<',now())->count(), 'topWorkers'=>User::role('worker')->withCount(['workerOrders as completed_tasks'=>fn($q)=>$q->where('status',OrderStatus::Completed)])->orderByDesc('completed_tasks')->limit(5)->get(['id','name'])]; } private function worker(User $user): array { return ['assignedTasks'=>$user->workerOrders()->whereNotIn('status',[OrderStatus::Completed,OrderStatus::Cancelled])->count(), 'deadlines'=>$user->workerOrders()->orderBy('deadline')->limit(5)->get(), 'earnings'=>$user->workerOrders()->where('status',OrderStatus::Completed)->sum('worker_fee'), 'completedTasks'=>$user->workerOrders()->where('status',OrderStatus::Completed)->count()]; } private function customer(User $user): array { return ['orderHistory'=>$user->customerOrders()->latest()->limit(10)->get(), 'activeOrders'=>$user->customerOrders()->whereNotIn('status',[OrderStatus::Completed,OrderStatus::Cancelled])->count(), 'invoices'=>Payment::whereHas('order',fn($q)=>$q->where('customer_id',$user->id))->latest()->limit(10)->get()]; } private function affiliate(User $user): array { return ['clicks'=>0, 'conversions'=>$user->referrals()->where('status','approved')->count(), 'earnings'=>$user->referrals()->sum('reward_amount'), 'withdrawals'=>Withdrawal::where('user_id',$user->id)->latest()->limit(10)->get()]; } }
